import{_ as t,o as s,c as n,a0 as o}from"./chunks/framework.1R7PBCUH.js";const a="/computer-fundamentals/assets/vb_network_tools.EdcP7JNn.png",i="/computer-fundamentals/assets/vb_hostonly_network.DRIvor3B.png",r="/computer-fundamentals/assets/vb_network_settings.eX0FXa6g.png",h="/computer-fundamentals/assets/network_connections.BRYtzuKH.png",l="/computer-fundamentals/assets/ip_address.ByT7sfBV.png",c="/computer-fundamentals/assets/ssh_connection.CyyQ0U4M.png",b=JSON.parse('{"title":"Remote Login","description":"","frontmatter":{},"headers":[],"relativePath":"labs/remote-login.md","filePath":"labs/remote-login.md"}'),p={name:"labs/remote-login.md"};function d(u,e,g,m,y,k){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="remote-login" tabindex="-1">Remote Login <a class="header-anchor" href="#remote-login" aria-label="Permalink to &quot;Remote Login&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>This lab is still in draft. It contains all the information you need, but the text isn&#39;t polished yet.</p></div><p>In this lab, you&#39;ll learn how you can use <strong>SSH</strong> to connect to a Linux system remotely. You&#39;ll set up an SSH server on your virtual machine and connect to it from your host machine.</p><h2 id="about-ssh" tabindex="-1">About SSH <a class="header-anchor" href="#about-ssh" aria-label="Permalink to &quot;About SSH&quot;">​</a></h2><p><strong>SSH</strong> (<em>secure shell</em>) is a network protocol used for secure remote login. You can use SSH to open a shell on a remote machine, send commands to it, and copy files over.</p><p>To use SSH, you need an SSH <strong>server</strong> on the machine you want to connect to, and an SSH <strong>client</strong> on the machine you want to connect from. In this lab, you&#39;ll install an SSH server on your Ubuntu virtual machine and connect to it from your Windows, macOS, or Linux host machine.</p><h2 id="installing-an-ssh-server" tabindex="-1">Installing an SSH server <a class="header-anchor" href="#installing-an-ssh-server" aria-label="Permalink to &quot;Installing an SSH server&quot;">​</a></h2><p>Use <code>apt</code> to install the <strong>openssh-server</strong> package:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssh-server</span></span></code></pre></div><p>This package registers an <strong>ssh</strong> system service. Start this service with the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><p>Also <em>enable</em> the service so that it starts automatically when you start the system:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><p>Finally, check the status of the service to confirm that it&#39;s active and enabled:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><p>Your SSH server is now active and listening on port <strong>22</strong>, which is the default for SSH.</p><h2 id="additional-configuration-for-virtualbox" tabindex="-1">Additional configuration for VirtualBox <a class="header-anchor" href="#additional-configuration-for-virtualbox" aria-label="Permalink to &quot;Additional configuration for VirtualBox&quot;">​</a></h2><p>To connect to your SSH server, you need a network connection between your host and virtual machine. In VirtualBox, you need to configure a <strong>host-only network</strong>. In UTM, this step is not required, so you can skip these instructions and continue with the next section.</p><p>Press <code>Ctrl+H</code> to open the VirtualBox Network Tools:</p><p><img src="'+a+'" alt="Network tools"></p><p>Create a host-only network:</p><p><img src="'+i+'" alt="Creating a host-only network"></p><p>By default, the network will be set to <strong>192.168.56.1/24</strong>. Confirm that its DHCP server is enabled.</p><p>Next, open the network settings for your virtual machine:</p><p><img src="'+r+'" alt="Configuring the host-only network"></p><p>Enable the second network adapter and attach it to the host-only network you created earlier. Do not change the first network adapter because you need it to connect to the internet. The second adapter only creates a connection between your virtual machine and your host; it cannot connect to the internet.</p><p>Restart your virtual machine. You&#39;ll confirm the host-only network is working in the following sections.</p><h2 id="finding-your-ip-address" tabindex="-1">Finding your IP address <a class="header-anchor" href="#finding-your-ip-address" aria-label="Permalink to &quot;Finding your IP address&quot;">​</a></h2><p>To connect to your SSH server, you need to know the <strong>IP address</strong> of your virtual machine.</p><p>Open the Settings app, go to Network, and click the gear icon next to your network connection:</p><p><img src="'+h+'" alt="List of network connections"></p><p>In VirtualBox, you&#39;ll have two connections. Click the gear icon next to the second connection, labeled <strong>enp0s8</strong> in the screenshot above. This should be your host-only network.</p><p>In the connection details, find the field labeled <strong>IPv4 Address</strong>. In the screenshot below, my address is 192.168.64.8:</p><p><img src="'+l+'" alt="Viewing your IP address"></p><p>In the next section, you&#39;ll use this address to connect to your virtual machine.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>All subsequent examples will use my IP address <code>192.168.64.8</code> and my username <code>steven</code>. Replace these with the IP address of your virtual machine and your username.</p></div><h2 id="using-an-ssh-client" tabindex="-1">Using an SSH client <a class="header-anchor" href="#using-an-ssh-client" aria-label="Permalink to &quot;Using an SSH client&quot;">​</a></h2><p>Leave your virtual machine running and open a terminal on your <em>host</em> machine. On macOS or Linux, open the <strong>Terminal</strong> app. On Windows, open either <strong>Terminal</strong>, <strong>PowerShell</strong>, or <strong>Command Prompt</strong>. All of these should have the commands you need preinstalled.</p><p>In this terminal, use the <strong><code>ping</code></strong> command to test the network connection between your host and virtual machine. Specify the IP address of your virtual machine as an argument:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.64.8</span></span></code></pre></div><p>This command sends small packets back and forth and reports how long they took to arrive. If the command keeps pinging indefinitely, press <code>Ctrl+C</code> to stop it.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>If <code>ping</code> shows network errors or timeouts, verify that you&#39;re using the correct IP address. On VirtualBox, verify that your host-only network is configured correctly, and that you&#39;re pinging the host-only adapter, not the original one, as they have different addresses.</p></div><p>Now that you have a working connection, use the <strong><code>ssh</code></strong> command to connect to your virtual machine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> steven@192.168.64.8</span></span></code></pre></div><p>Here, you specify both the IP address of the machine you want to connect to and your username on that machine. You can also specify the port with the <code>-p</code> option:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> steven@192.168.64.8</span></span></code></pre></div><p>However, this is not required when you&#39;re using the default port of 22.</p><p>When you start an SSH session, the server will prompt you for the password for the username you provided. If that password is correct, the server prints a welcome message and opens a shell. Here&#39;s what that looks like for me, connecting from a macOS host:</p><p><img src="'+c+'" alt="Established SSH connection"></p><p>Any commands you type here are executed on your virtual machine, even though you&#39;re using a terminal on your host machine. Try running the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hello!&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/hello.txt</span></span></code></pre></div><p>This command creates a file on your desktop. Verify that this file was created, then return to your SSH session and try a few more commands. When you&#39;re done, use the <code>exit</code> command to close your session and return to your original shell.</p><p>Using SSH to connect to a virtual machine that&#39;s running on your own device may not be very interesting. However, that same <code>ssh</code> command can connect to <em>any</em> machine that has an SSH server. All you need is an IP address and your username and password.</p><p>In <a href="./../exercises/exercises6.html#bandit">Exercise 6.3</a>, you&#39;ll use SSH to connect to a remote server over the internet.</p><h2 id="copying-files-over-ssh" tabindex="-1">Copying files over SSH <a class="header-anchor" href="#copying-files-over-ssh" aria-label="Permalink to &quot;Copying files over SSH&quot;">​</a></h2><p>SSH lets you copy files over the network through the <strong><code>scp</code></strong> (<em>Secure Copy Protocol</em>) command. To try this out, open a terminal on your host machine, but don&#39;t start an SSH session.</p><p>Run the following command to copy the file you created earlier from the desktop on your virtual machine to the current directory on your host machine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;steven@192.168.64.8:~/Desktop/hello.txt&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>This command specifies a remote path to <strong>hello.txt</strong> by prefixing an IP address and a username. The quotes around this path prevent the tilde from getting parsed on your host machine, since it refers to your home directory on the virtual machine.</p><p><code>scp</code> is very useful for quickly copying files over the network. Behind the scenes, this command actually uses <strong>SFTP</strong> (<em>SSH File Transfer Protocol</em>) instead of the outdated Secure Copy Protocol it was originally named after. SFTP is more secure and more versatile than SCP. You&#39;ll try it out in <a href="./../exercises/exercises6.html#sftp">Exercise 6.2</a>.</p><h2 id="up-next" tabindex="-1">Up next <a class="header-anchor" href="#up-next" aria-label="Permalink to &quot;Up next&quot;">​</a></h2><p>This concludes the final lab for this course. Before you wrap up, work your way through the final exercises, where you&#39;ll practice using SSH and SFTP.</p>',62)])])}const f=t(p,[["render",d]]);export{b as __pageData,f as default};
